const basicFeatureIconNames=["calculator-simple", "books", "copy", "euro", "layout-fluid"];
const packageFeatureIds={"basic": ["prices", "library", "models", "margins", "imposition"], "commerce": ["products", "shop-prices", "orders", "connector"], "edition": ["authoring", "personalization", "graphics", "creation-save"], "gestion": ["management-quotes", "management-jobs", "management-invoices", "management-insights", "management-connectors"]};
const commerceFeatureIconNames=["apps", "calculator-simple", "shopping-cart-check", "link-alt"];
const editionFeatureIconNames=["file-edit", "pencil", "picture", "disk"];
const gestionFeatureIconNames=["handshake", "task-checklist", "euro", "overview", "link-alt"];
function featureIcon(index,owner="basic"){const name=({commerce:commerceFeatureIconNames,edition:editionFeatureIconNames,gestion:gestionFeatureIconNames}[owner]||basicFeatureIconNames)[index];return `<svg class="solution-feature-icon" width="18" height="18" viewBox="0 0 300 300" data-uicon="${name}" aria-hidden="true" focusable="false"><g transform="translate(0 300) scale(1 -1)" fill="currentColor"><path d="${basicFeatureIcons[name]}"/></g></svg>`;}
function zoomButton(id){return `<button type="button" class="solution-zoom-trigger" data-zoom="${id}" aria-haspopup="dialog" aria-label="En savoir plus sur ${solutionDetails[id].title}" title="En savoir plus">${zoomIcon}</button>`;}
function inlineDetailTitle(text,id,isOption=false){
 const title=isOption?`<label for="option-${id}">${text}</label>`:`<span>${text}</span>`;
 return `<span class="detail-title-row">${title}${zoomButton(id)}</span>`;
}
const packageIncludedDetails={edition:['Prévisualisation et partage 2D et 3D','preview'],commerce:['Configuration et mise en ligne de votre premier produit','shop-start'],gestion:['Générateurs de devis et de fiches de fabrication','management-documents']};
// Commercial working prices: all amounts are EUR excluding VAT, no checkout.
const configurationPricing={
 solutions:{basic:{cadence:'Abonnement',amount:159,annualAmount:149},commerce:{cadence:'Abonnement',amount:159,annualAmount:149},edition:{cadence:'Abonnement',amount:159,annualAmount:149},gestion:{cadence:'Abonnement',amount:219,annualAmount:199}},
 options:{pdf:{cadence:'Abonnement',amount:32,annualAmount:29},sheet:{cadence:'Abonnement',amount:10,annualAmount:9},quote:{cadence:'Abonnement',amount:10,annualAmount:9},b2b:{cadence:'Abonnement',amount:109,annualAmount:99},impose:{cadence:'Abonnement',amount:54,annualAmount:49},planning:{cadence:'Abonnement',amount:32,annualAmount:29},webshop:{cadence:'Prestation ponctuelle',amount:null,label:'Sur devis'},templates:{cadence:'À l’usage',amount:null,label:'Simple : 0,99 € · Complexe : 1,49 € par utilisation'},'management-automation':{cadence:'Intégration et maintenance',amount:null,label:'Sur devis'}},
 allIn:{monthly:749,annualMonthly:699,options:['pdf','b2b','impose','planning']}
};
let billingPeriod='monthly';
const euros=n=>new Intl.NumberFormat('fr-BE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
const discountPercent=(amount,base)=>new Intl.NumberFormat('fr-BE',{maximumFractionDigits:1}).format(amount/base*100);
function solutionPrice(id,period='monthly'){const p=configurationPricing.solutions[id];return period==='annual'?p.annualAmount:p.amount;}
function optionAmount(id,period='monthly'){const p=configurationPricing.options[id];return period==='annual'?(p.annualAmount??p.amount):p.amount;}
function optionPrice(id){const p=configurationPricing.options[id];if(id==='templates')return 'Simple : 0,99 € HT<span class="option-annual">Complexe : 1,49 € HT<br>Par utilisation · hors abonnement</span>';return p.amount===null?p.label:`${euros(p.amount)} HT / mois<span class="option-annual">ou ${euros(p.annualAmount)} HT / mois en annuel</span>`;}
function pricingSummary(period=billingPeriod){
 const allIn=packages.every(p=>selected.has(p.id))&&configurationPricing.allIn.options.every(id=>options.has(id));
 const subtotal=packages.filter(p=>selected.has(p.id)).reduce((sum,p)=>sum+solutionPrice(p.id,period),0)+[...options].reduce((sum,id)=>sum+(optionAmount(id,period)||0),0);
 const monthly=allIn?(period==='annual'?configurationPricing.allIn.annualMonthly:configurationPricing.allIn.monthly):subtotal;
 return {allIn,subtotal,monthly,discount:subtotal-monthly,annual:monthly*12};
}
function configurationTotals(){
 const m=pricingSummary('monthly'),a=pricingSummary('annual');
 return `<tfoot><tr><th colspan="2" scope="row">Abonnements à la carte · HT / mois</th><td class="configuration-price">${euros(m.subtotal)}</td><td class="configuration-price">${euros(a.subtotal)}</td></tr>${m.allIn?`<tr><th colspan="2" scope="row">Remise All-in</th><td class="configuration-price">−${euros(m.discount)}</td><td class="configuration-price">−${euros(a.discount)}</td></tr>`:''}<tr class="configuration-total"><th colspan="2" scope="row">Total HT / mois</th><td class="configuration-price">${euros(m.monthly)}</td><td class="configuration-price">${euros(a.monthly)}</td></tr><tr><th colspan="2" scope="row">Montant facturé HT</th><td class="configuration-price">${euros(m.monthly)}<small>chaque mois</small></td><td class="configuration-price">${euros(a.annual)}<small>une fois par an</small></td></tr></tfoot>`;
}
const selected=new Set(['basic']), options=new Set();
const byId=id=>document.getElementById(id);
byId('cards').innerHTML=packages.map(p=>`<article class="package ${p.id}" aria-labelledby="title-${p.id}"><div class="package-top"><div class="kicker"><span class="solution-marker"><svg width="16" height="16" viewBox="0 0 300 300" aria-hidden="true" focusable="false"><g transform="translate(0 300) scale(1 -1)" fill="currentColor"><path d="${solutionIcons[p.id]}"/></g></svg></span><span class="tag">${p.tag}</span></div><h3 id="title-${p.id}">${p.name}</h3><p class="intro">${p.intro}</p><div class="package-price"><div><strong>${euros(solutionPrice(p.id))}</strong><span> HT / mois</span></div><small>ou <b>${euros(solutionPrice(p.id,'annual'))} HT / mois</b> en annuel<br>${euros(solutionPrice(p.id,'annual')*12)} HT facturés par an</small></div><button class="toggle" data-package="${p.id}" aria-pressed="false">Ajouter à ma sélection</button></div><div class="package-body"><div class="package-inclusions"><div class="mini-title">LES FONCTIONNALITÉS</div><ul class="features">${p.features.map((f,i)=>`<li>${packageFeatureIds[p.id]?featureIcon(i,p.id):checkIcon}<span class="feature-name">${packageFeatureIds[p.id]?inlineDetailTitle(f.label,packageFeatureIds[p.id][i]):f.label}<small>${f.description}</small></span></li>`).join('')}</ul>${packageIncludedDetails[p.id]?`<div class="package-included-note"><span class="included">INCLUS</span>${inlineDetailTitle(...packageIncludedDetails[p.id])}</div>`:''}</div><div class="addons"><div class="mini-title">POUR ALLER PLUS LOIN</div>${p.options.map(([id,label,desc])=>{const option=`<label class="option"><input type="checkbox" id="option-${id}" data-option="${id}" data-owner="${p.id}"><span>${label}<small data-description="${id}">${desc}</small></span></label>`;return solutionDetails[id]?`<div class="option option-with-zoom"><input type="checkbox" id="option-${id}" data-option="${id}" data-owner="${p.id}" aria-describedby="description-${id}"><div class="option-copy">${inlineDetailTitle(label,id,true)}<small id="description-${id}" data-description="${id}">${desc}</small><span class="option-price" data-price="${id}">${optionPrice(id)}</span></div></div>`:option;}).join('')}</div></div></article>`).join('');
function getSummary(){
 const names=packages.filter(p=>selected.has(p.id)).map(p=>p.name);
 const extra=packages.flatMap(p=>p.options.filter(([id])=>options.has(id)).map(([,name])=>name));
 return {names,extra};
}
function configurationSolutions(){
 return packages.filter(p=>selected.has(p.id));
}
const configurationFeatures={
 basic:[['Calcul des coûts et des prix de vente','prices'],['Simulation et comparaison de variantes','prices'],['Bibliothèque des supports, équipements et prestations','library'],['Enregistrement et réutilisation des modèles de calcul','models'],['Paramétrage des marges et règles commerciales','margins'],['Calcul de l’imposition et des besoins en feuilles','imposition']],
 commerce:[['Configuration des produits et des options de vente','products'],['Calcul des prix en ligne via Presstora Calculs','shop-prices'],['Gestion des commandes et des livraisons','orders'],['Connecteur e-commerce — WooCommerce','connector']],
 edition:[['Préparation des modèles et des zones modifiables','authoring'],['Personnalisation des créations','personalization'],['Gestion des ressources graphiques','graphics'],['Sauvegarde des projets et export PDF','creation-save']],
 gestion:[['Création des devis et propositions commerciales','management-quotes'],['Organisation et suivi de la fabrication','management-jobs'],['Facturation et suivi des paiements','management-invoices'],['Statistiques économiques et de production','management-insights'],['Connecteurs Peppol et comptabilité','management-connectors']]
};
function configurationRows(p){
 const ref=String(packages.indexOf(p)+1).padStart(2,'0');
 const rows=configurationFeatures[p.id].map(([label,id],i)=>({ref:ref+'.'+String(i+1).padStart(2,'0'),label,id,kind:'feature',billing:'Compris',price:'Inclus'}));
 const included=packageIncludedDetails[p.id];
 if(included)rows.push({ref:ref+'.'+String(rows.length+1).padStart(2,'0'),label:included[0],id:included[1],kind:'included',billing:p.id==='commerce'?'Service inclus':'Compris',price:'Inclus'});
 p.options.forEach(([id,label],i)=>{if(options.has(id))rows.push({ref:ref+'.'+String.fromCharCode(65+i),label:'Option · '+label+(id==='b2b'?' · illimité':''),id,kind:'option',billing:configurationPricing.options[id].cadence,price:configurationPricing.options[id].amount===null?configurationPricing.options[id].label:euros(optionAmount(id)),annualPrice:configurationPricing.options[id].amount===null?configurationPricing.options[id].label:euros(optionAmount(id,'annual'))});});
 return {ref,rows};
}
function renderConfiguration(p){
 const {ref,rows}=configurationRows(p);
 const icon=`<svg class="configuration-icon" width="22" height="22" viewBox="0 0 300 300" aria-hidden="true"><g transform="translate(0 300) scale(1 -1)" fill="currentColor"><path d="${solutionIcons[p.id]}"/></g></svg>`;
 return `<tbody class="configuration-solution ${p.id}" aria-labelledby="configuration-${p.id}"><tr class="configuration-solution-heading"><td class="configuration-reference">${ref}</td><th scope="rowgroup" id="configuration-${p.id}"><span class="configuration-name">${icon}Presstora ${p.name}</span><small>${p.tag}</small></th><td class="configuration-price">${euros(solutionPrice(p.id))}</td><td class="configuration-price">${euros(solutionPrice(p.id,'annual'))}</td></tr>${rows.map(r=>`<tr class="configuration-${r.kind}"><td class="configuration-reference">${r.ref}</td><td>${inlineDetailTitle(r.label,r.id)}${r.kind==='option'&&configurationPricing.options[r.id].amount===null?`<small class="configuration-planned">${r.billing} · en supplément</small>`:''}${['management-connectors','management-automation'].includes(r.id)?'<small class="configuration-planned">En préparation</small>':''}</td>${r.kind==='option'&&configurationPricing.options[r.id].amount===null?`<td colspan="2" class="configuration-price">${r.price}</td>`:`<td class="configuration-price">${r.price}</td><td class="configuration-price">${r.annualPrice??r.price}</td>`}</tr>`).join('')}</tbody>`;
}
function update(){
 const required=selected.has('commerce')||selected.has('gestion');
 if(required) selected.add('basic');
 for(const p of packages){
  const button=document.querySelector(`[data-package="${p.id}"]`),on=selected.has(p.id);
  button.setAttribute('aria-pressed',String(on));button.disabled=p.id==='basic'&&required;
  button.innerHTML=(on?checkIcon:addIcon)+'<span>'+(button.disabled?'Socle requis et sélectionné':on?'Dans ma sélection':'Ajouter à ma sélection')+'</span>';
  for(const [id,,desc] of p.options){
   const input=byId('option-'+id),included=selected.has('gestion')&&['sheet','quote'].includes(id);
   input.disabled=!on||included;input.checked=included||options.has(id);
   if(!on||included) options.delete(id);
   input.checked=included||options.has(id);
   const description=document.querySelector(`[data-description="${id}"]`);
   description.textContent=included?'Inclus avec Gestion':desc;
   for(const label of input.labels)label.title=!on?'Sélectionnez cette solution pour ajouter cette option':'';
   description.classList.toggle('included',included);
   document.querySelector(`[data-price="${id}"]`).innerHTML=included?'Sans supplément':optionPrice(id);
  }
 }
 const {names,extra}=getSummary();
 byId('count').textContent=names.length;
 byId('selected-packages').innerHTML=names.length?`<table class="configuration-table"><caption class="configuration-sr-only">Composition de votre configuration Presstora</caption><colgroup><col class="configuration-reference-column"><col><col class="configuration-price-column"><col class="configuration-price-column"></colgroup><thead><tr><th scope="col">Réf.</th><th scope="col">Désignation <span class="configuration-unit">· Tarifs HT / mois</span></th><th scope="col">Mensuel</th><th scope="col">Annuel</th></tr></thead>${configurationSolutions().map(renderConfiguration).join('')}${configurationTotals()}</table>`:'<div class="configuration-empty"><h3>Votre configuration commence ici.</h3><p>Choisissez une solution dans le tableau ci-dessus pour retrouver son contenu ici.</p><a href="#packages">Découvrir les solutions ↑</a></div>';
 const tariff=pricingSummary(),monthly=pricingSummary('monthly'),annual=pricingSummary('annual');
 byId('configuration-plan').textContent=tariff.allIn?'Presstora All-in':'À la carte';
 byId('summary-monthly-price').textContent=names.length?euros(monthly.monthly):'—';
 byId('summary-annual-price').textContent=names.length?euros(annual.monthly):'—';
 byId('summary-annual-payment').textContent=names.length?euros(annual.annual)+' HT facturés par an':'Aucune solution sélectionnée';
 for(const period of ['monthly','annual']){
  const ref=byId('summary-'+period+'-reference');ref.hidden=period==='annual'?!(names.length&&annual.monthly<monthly.monthly):!tariff.allIn;ref.textContent=euros(period==='annual'?monthly.monthly:monthly.subtotal);
  ref.setAttribute('aria-label',period==='annual'?'Tarif avec paiement mensuel':'Valeur à la carte en paiement mensuel');
  byId('summary-'+period+'-comparison').hidden=ref.hidden;
  byId('summary-'+period+'-percent').textContent=ref.hidden?'':'≈ −'+discountPercent(period==='annual'?monthly.monthly-annual.monthly:monthly.discount,period==='annual'?monthly.monthly:monthly.subtotal)+' %';
  byId('billing-'+period).disabled=!names.length;
 }
 byId('summary-monthly-saving').hidden=!tariff.allIn;
 byId('summary-monthly-saving').textContent=tariff.allIn?euros(monthly.discount)+' économisés chaque mois par rapport à la carte':'';
 byId('summary-annual-saving').hidden=!names.length||annual.monthly>=monthly.monthly;
 byId('summary-annual-saving').textContent=names.length&&annual.monthly<monthly.monthly?euros((monthly.monthly-annual.monthly)*12)+' économisés par an':'';
 byId('summary-same-price').hidden=annual.monthly!==monthly.monthly||!names.length;
 const extraLines=packages.flatMap(p=>p.options.filter(([id])=>options.has(id)&&configurationPricing.options[id].amount===null).map(([id,label])=>`<li>${label} : ${configurationPricing.options[id].label.toLowerCase()}</li>`));
 byId('summary-extras').hidden=!extraLines.length;
 byId('summary-extras-list').innerHTML=extraLines.join('');
 byId('choose-all-in').textContent=tariff.allIn?'All-in dans ma sélection':'Choisir Presstora All-in';
 byId('choose-all-in').setAttribute('aria-pressed',String(tariff.allIn));
 byId('download').disabled=!names.length;
 byId('feedback').textContent='';
}
